// ★★★ THE SIX DESTINATIONS OF THE HUB, DERIVED FROM `seed/box.json` AND HANDED TO AN APP THAT CANNOT READ IT.
//
//   node bin/gate-faces.mjs            print what this box declares (and what it would write)
//   node bin/gate-faces.mjs --write    regenerate apps/demo-gate/faces.generated.ts
//   node --test bin/gate-faces.guard.mjs
//
// ── WHY A GENERATED FILE AND NOT A READ ─────────────────────────────────────────────────────────────────
//
// `apps/demo-gate` is baked INTO the kernel image: `bin/build-local.sh` rsyncs that one directory into the
// oven's context (`--exclude design-base`) and nothing else of this repository travels with it. So the gate's
// screen cannot read `seed/box.json` at runtime — the file is not there — and it must not carry a hostname
// somebody typed either, because the addresses are DATA this box already declares once (pk34/d1: «a hostname
// is data and belongs here»). The wire between the two is this generator: the declaration stays the one
// source, the app gets a module, and `bin/gate-faces.guard.mjs` makes the two unable to drift.
//
// ⚠️ AND A FACE WITH NO ADDRESS IS CARRIED, NOT DROPPED. `bin/box-domains.mjs::declaredFaces` skips a store
// that declares no `domain`, which is right for the EDGE — there is nothing to route. It is wrong here: a
// destination the hub cannot address is a destination the visitor must be TOLD about, never one that quietly
// leaves the screen. So `host`/`env` are nullable, and the screen names what it could not address.
//
// ⛔ NOTHING HERE NAMES A TENANT, A STORE OR A HOSTNAME. A fifth store declared tomorrow is a card tomorrow.

import { readFileSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { ROOT, readBox } from './box-domains.mjs';

/** The module this generator owns, end to end. Its first line says so, and the guard re-derives it. */
export const GENERATED_FILE = 'apps/demo-gate/faces.generated.ts';

/**
 * Every face of this box, in declaration order, tenant by tenant — the shape the hub draws.
 *
 * A face is one destination of the hub. `kind` is `admin` for the tenant's own admin and `shop` for a store;
 * `host`/`env` are what `seed/box.json` declares, or `null` when it declares none.
 *
 * @returns {{ id: string, name: string, faces: { key: string, kind: 'shop'|'admin', tenant: string, store: string|null, host: string|null, env: string|null }[] }[]}
 */
export function hubTenants(box = readBox()) {
  return (box.tenants ?? []).map((tenant) => {
    const faces = [];
    for (const store of tenant.stores ?? []) {
      faces.push({
        key: `${tenant.id}/${store.handle}`,
        kind: 'shop',
        tenant: tenant.id,
        store: store.handle,
        host: store.domain?.host ?? null,
        env: store.domain?.env ?? null,
      });
    }
    // The admin is LAST on purpose: it is the row at the foot of the design's tenant card, under the shops.
    faces.push({
      key: `${tenant.id}/admin`,
      kind: 'admin',
      tenant: tenant.id,
      store: null,
      host: tenant.admin_domain?.host ?? null,
      env: tenant.admin_domain?.env ?? null,
    });
    return { id: tenant.id, name: tenant.settings?.tenant_name ?? tenant.id, faces };
  });
}

/** Every face, flat — what the hub counts and what the guard grades. */
export const hubFaces = (box = readBox()) => hubTenants(box).flatMap((t) => t.faces);

/** The module's text, byte for byte. The guard compares this with the file on disk. */
export function render(box = readBox()) {
  const tenants = hubTenants(box);
  const body = JSON.stringify(tenants, null, 2);
  return `// ⛔ GENERATED by \`node bin/gate-faces.mjs --write\` from seed/box.json. DO NOT EDIT.
//
// The hub's destinations — one card per store, one row per tenant admin. This file exists because
// \`apps/demo-gate\` is baked into the kernel image ALONE (bin/build-local.sh rsyncs this directory and
// nothing else of the box), so the screen cannot read the declaration it is derived from. The guard that
// keeps the two identical is \`bin/gate-faces.guard.mjs\`.
//
// \`host\`/\`env\` are \`null\` for a face \`seed/box.json\` declares NO address for. That is carried rather
// than dropped: a destination the hub cannot address is one the visitor must be told about.

/** One destination of the hub. */
export type GateFace = {
  /** \`<tenant>/<store handle>\` for a shop, \`<tenant>/admin\` for an admin. The key the copy is written against. */
  key: string;
  kind: 'shop' | 'admin';
  tenant: string;
  /** The store's handle, or \`null\` for a tenant's admin. */
  store: string | null;
  /** The hostname this box publishes the face at, or \`null\` when it declares none. */
  host: string | null;
  /** The variable seed/box.json names to carry that hostname to the edge, or \`null\`. */
  env: string | null;
};

/** One card of the hub: a tenant, and the faces it publishes, in declaration order. */
export type GateTenant = { id: string; name: string; faces: GateFace[] };

export const GATE_TENANTS: GateTenant[] = ${body};

/** Every face, flat — what the screen counts and what its test holds against seed/box.json. */
export const GATE_FACES: GateFace[] = GATE_TENANTS.flatMap((tenant) => tenant.faces);
`;
}

const path = () => join(ROOT, GENERATED_FILE);

/** What is on disk today, or the empty string when the module has never been written. */
export function onDisk() {
  try {
    return readFileSync(path(), 'utf8');
  } catch {
    return '';
  }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const text = render();
  if (process.argv.includes('--write')) {
    writeFileSync(path(), text);
    console.error(`[gate-faces] wrote ${GENERATED_FILE}`);
  }
  for (const tenant of hubTenants()) {
    for (const face of tenant.faces) {
      console.error(
        `[gate-faces] ${face.key.padEnd(20)} ${face.kind.padEnd(5)} ${face.host ?? '⚠️ NO ADDRESS DECLARED'}`,
      );
    }
  }
}
